#include <bits/stdc++.h>
using namespace std;

const int maxSize = 200001;
const long long mod = 998244353;

long long factorials[maxSize];

long long fastPower(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

long long nCr(int n, int k) {
    if (n < k) return 0;
    long long numerator = factorials[n];
    long long denominator = (factorials[n - k] * factorials[k]) % mod;
    return (numerator * fastPower(denominator, mod - 2)) % mod;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    for (int i = 0; i < maxSize; i++) {
        factorials[i] = (i == 0) ? 1 : (factorials[i - 1] * i) % mod;
    }
    int n;
    long long k;
    cin >> n >> k;
    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }
    if (k == 0) {
        cout << factorials[n] << "\n";
        return 0;
    }
    if (k == n - 1) {
        cout << 2LL * n << "\n";
        return 0;
    }
    int filledCols = n - (int)k;
    long long waysToChooseFilledCols = nCr(n, filledCols);
    long long ans = 0;
    for (int emptyCols = 0; emptyCols <= filledCols; emptyCols++) {
        long long waysToChoose = nCr(filledCols, emptyCols);
        long long waysToFill = fastPower(filledCols - emptyCols, n);
        long long val = (waysToChoose * waysToFill) % mod;
        if (emptyCols % 2 == 1) {
            val = (mod - val) % mod;
        }
        ans = (ans + val) % mod;
    }
    ans = (ans * waysToChooseFilledCols) % mod;
    ans = (ans * 2) % mod;
    cout << ans << "\n";
    return 0;
}
